BEGIN;
SET LOCAL statement_timeout='30s';
DO $$ DECLARE native uuid;actor uuid;org uuid:=gen_random_uuid();foreign_org uuid:=gen_random_uuid();client uuid:=gen_random_uuid();foreign_client uuid:=gen_random_uuid();retailer uuid;store uuid:=gen_random_uuid();visit uuid:=gen_random_uuid();finding uuid:=gen_random_uuid();action uuid:=gen_random_uuid();foreign_action uuid:=gen_random_uuid();foreign_visit uuid:=gen_random_uuid();foreign_finding uuid:=gen_random_uuid();r jsonb;n int;
BEGIN
 SELECT target_user_id,source_user_id INTO native,actor FROM tj.source_user_identity_map WHERE identity_verified AND activation_status='activated' AND mapping_status IN('approved_map','approved_create','approved_invite') AND approved_at IS NOT NULL LIMIT 1;
 IF native IS NULL THEN RAISE EXCEPTION 'Missing fixture identity';END IF;
 SELECT id INTO retailer FROM tj.field_retailers LIMIT 1;
 INSERT INTO tj.organizations(id,name,slug) VALUES(org,'Rollback Field',org::text),(foreign_org,'Rollback Foreign Field',foreign_org::text);
 INSERT INTO tj.organization_members(organization_id,user_id,role,status) VALUES(org,actor,'admin','active');
 INSERT INTO tj.field_clients(id,organization_id,client_name) VALUES(client,org,'Rollback Client'),(foreign_client,foreign_org,'Rollback Foreign Client');
 INSERT INTO tj.field_stores(id,retailer_id,store_name) VALUES(store,retailer,'Rollback Store');
 INSERT INTO tj.field_visits(id,client_id,store_id,rep_user_id) VALUES(visit,client,store,actor),(foreign_visit,foreign_client,store,actor);
 INSERT INTO tj.field_findings(id,visit_id,client_id,store_id) VALUES(finding,visit,client,store),(foreign_finding,foreign_visit,foreign_client,store);
 INSERT INTO tj.field_actions(id,finding_id,visit_id,client_id,store_id,title) VALUES(action,finding,visit,client,store,'Rollback Action'),(foreign_action,foreign_finding,foreign_visit,foreign_client,store,'Foreign Action');
 PERFORM set_config('request.jwt.claim.sub',native::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',native,'email','spoof@example.invalid','user_metadata',jsonb_build_object('role','owner'))::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.tj_runtime_field_report('snapshot',org);
 IF jsonb_array_length(r->'actions')<>1 OR r->'actions'->0->>'id'<>action::text OR jsonb_array_length(r->'clients')<>1 THEN RAISE EXCEPTION 'Tenant read isolation failed';END IF;
 BEGIN PERFORM public.tj_runtime_field_report('snapshot',foreign_org);RAISE EXCEPTION 'Foreign workspace exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_field_report('status',org,foreign_action,'{"status":"resolved","expected_status":"new"}');RAISE EXCEPTION 'Foreign action changed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_field_report('status',org,action,jsonb_build_object('status','reviewed','expected_status','new','changed_by_user_id',gen_random_uuid()));RAISE EXCEPTION 'Author spoof accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'unsupported_status_field' THEN RAISE;END IF;END;
 BEGIN PERFORM public.tj_runtime_field_report('status',org,action,'{"status":"invented","expected_status":"new"}');RAISE EXCEPTION 'Unknown status accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invalid_status' THEN RAISE;END IF;END;
 r:=public.tj_runtime_field_report('status',org,action,'{"status":"reviewed","expected_status":"new","notes":"Fixture review"}');
 IF r->>'status'<>'reviewed' THEN RAISE EXCEPTION 'Status update failed';END IF;
 r:=public.tj_runtime_field_report('snapshot',org);
 IF jsonb_array_length(r->'history')<>1 OR r->'history'->0->>'old_status'<>'new' OR r->'history'->0->>'changed_by_user_id'<>actor::text THEN RAISE EXCEPTION 'Atomic history or server actor failed';END IF;
 BEGIN PERFORM public.tj_runtime_field_report('status',org,action,'{"status":"resolved","expected_status":"new"}');RAISE EXCEPTION 'Stale update accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 PERFORM public.tj_runtime_field_report('status',org,action,'{"status":"reviewed","expected_status":"reviewed"}');
 r:=public.tj_runtime_field_report('snapshot',org);IF jsonb_array_length(r->'history')<>1 THEN RAISE EXCEPTION 'No-op duplicated history';END IF;
 r:=public.tj_runtime_field_report('comment',org,action,'{"comment_text":"Rollback comment","visibility":"internal"}');
 IF r->>'author_user_id'<>actor::text OR r->>'visit_id'<>visit::text OR r->>'finding_id'<>finding::text THEN RAISE EXCEPTION 'Comment lineage or author failed';END IF;
 IF jsonb_array_length(public.tj_runtime_field_report('comments',org,action))<>1 THEN RAISE EXCEPTION 'Comments read failed';END IF;
 BEGIN PERFORM public.tj_runtime_field_report('export',org,NULL,jsonb_build_object('client_id',foreign_client,'export_type','fixture'));RAISE EXCEPTION 'Foreign export accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.tj_runtime_field_report('export',org,NULL,jsonb_build_object('client_id',client,'export_type','fixture'));
 IF r->>'generated_by_user_id'<>actor::text OR r->>'client_id'<>client::text THEN RAISE EXCEPTION 'Export identity failed';END IF;
 EXECUTE 'RESET ROLE';UPDATE tj.organization_members SET status='suspended' WHERE organization_id=org AND user_id=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.tj_runtime_field_report('snapshot',org);RAISE EXCEPTION 'Revoked membership retained access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';UPDATE tj.organization_members SET status='active',role='member' WHERE organization_id=org AND user_id=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.tj_runtime_field_report('snapshot',org);RAISE EXCEPTION 'Unreviewed member access accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';EXECUTE 'SET LOCAL ROLE anon';
 BEGIN PERFORM public.tj_runtime_field_report('context');RAISE EXCEPTION 'Anonymous execution accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
END $$;
ROLLBACK;
SELECT 'Field Report native scope, status/history, comment, export, conflict and revoked-access checks passed; fixtures rolled back' AS result;
